  python3 logprob_diff.py save  NAME      # score the current build, store it as NAME
  python3 logprob_diff.py check NAME      # score the current build, compare against NAME
  python3 logprob_diff.py compare A B     # compare two saved references (symmetric)

Teacher forcing: the reference continuation is fed as input with logprob_start_len=0, so
the model scores exactly the"    LOGPROB_MAX={overall['max']:.6f} LOGPROB_MEAN={overall['mean']:.6f}")


def main() -> None:
    if len(sys.argv) < 2:
        print(__doc__)
        sys.exit(1)
    cmd = sys.argv[1]
    if cmd == "save":
        name = sys.argv[2]
        payload = collect()
        (D / f"{name}.json").write_text(json.dumps(payload))
        for row in payload.values():
            print(f"  {name}: prompt {row['prompt_tokens']} tokens, "
                  f"{row['forced_tokens']} forced logprobs")
        return
    if cmd == "check":
        name = sys.argv[2]
        reference = json.loads((D / f"{name}.json").read_text())
        current = collect(cached=reference)
        report = stats(reference, current)
        print_report(f"{name} vs current", report)
        return
    if cmd == "compare":
        a, b = sys.argv[2], sys.argv[3]
        ra = json.loads((D / f"{a}.json").read_text())
        rb = json.loads((D / f"{b}.json").read_text())
        print_report(f"{b} vs {a}", stats(ra, rb))
        print_report(f"{a} vs {b}", stats(rb, ra))
        return
    sys.exit(f"unknown command {cmd}")


if __name__ == "__main__":
    main()


